style.css:
@-moz-document domain("youtube.com") {
/* Make the bottom controls relative for positioning */
  .ytp-chrome-bottom {
    position: relative !important;
  }

  /* Hide the original red progress dot */
  .ytp-progress-bar .ytp-play-progress {
    position: relative;
  }
  .ytp-progress-bar .ytp-play-progress .ytp-play-progress-thumb {
    display: none !important;
  }

  /* Add your GIF as the new "dot" */
  .ytp-progress-bar .ytp-play-progress::after {
    content: '';
    position: absolute;
    width: 30px; /* size of the GIF */
    height: 30px;
    top: -5px; /* move it above the bar */
    right: 0; /* moves with the progress automatically */
    background: url('https://image2url.com/r2/default/gifs/1770862203818-30f4e80a-da4c-40de-b2d9-f4fab351abdc.gif') no-repeat;
    background-size: cover;
    pointer-events: none;
    z-index: 9999;
  }
}
